import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"物品浏览 GUI","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/browser.md","filePath":"modules/item/browser.md","lastUpdated":0}`),a={name:`modules/item/browser.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="物品浏览-gui" tabindex="-1">物品浏览 GUI <a class="header-anchor" href="#物品浏览-gui" aria-label="Permalink to “物品浏览 GUI”">​</a></h1><p><code>/ei browse</code> 打开一个两级浏览界面：一级列出物品包，点包图标进入二级列出包内物品，左键取一件到背包（Shift + 左键取一整组）。</p><p>两级界面各有一份布局文件，都放在 <code>plugins/EmakiItem/gui/</code> 下：</p><table tabindex="0"><thead><tr><th>文件</th><th>层级</th><th>作用</th></tr></thead><tbody><tr><td><code>pack_browser_gui.yml</code></td><td>一级</td><td>列出 <code>items/</code> 下的每个物品包。</td></tr><tr><td><code>item_browser_gui.yml</code></td><td>二级</td><td>列出某个包内的全部物品。</td></tr></tbody></table><p>命令需要 <code>emakiitem.browse</code> 权限（默认 op），且<strong>只能由玩家执行</strong>。<code>/ei browse [页码]</code> 可直接跳到指定页，页码从 1 开始；小于 1 的值按第 1 页处理，超出总页数则打开一个空页，用翻页按钮可以退回。</p><h2 id="物品包元数据-pack-yml" tabindex="-1">物品包元数据 <code>pack.yml</code> <a class="header-anchor" href="#物品包元数据-pack-yml" aria-label="Permalink to “物品包元数据 pack.yml”">​</a></h2><p><code>items/</code> 下的每个子目录都可以放一份 <code>pack.yml</code>，定义该包在一级界面里的图标外观。</p><p>直接放在 <code>items/</code> 根目录下的物品也会构成一个「根包」：它的包 ID 是空串，同样出现在一级列表里，显示名取语言键 <code>browser.default_pack_name</code>。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;示例物品包&lt;/gold&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minecraft-chest&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;共 &lt;white&gt;%count%&lt;/white&gt; 件物品&lt;/gray&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;dark_gray&gt;包 ID: %pack%&lt;/dark_gray&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;yellow&gt;点击查看&lt;/yellow&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre></div><table tabindex="0"><thead><tr><th>键</th><th>缺省</th><th>说明</th></tr></thead><tbody><tr><td><code>display_name</code></td><td>目录名</td><td>一级界面显示的包名，支持 MiniMessage。留空回退为目录名。</td></tr><tr><td><code>icon</code></td><td><code>minecraft-chest</code></td><td>包图标，CoreLib ItemSource 简写，与物品定义的 <code>item.source</code> 同语法。</td></tr><tr><td><code>lore</code></td><td>显示物品数量</td><td>包图标的 lore。<code>%count%</code> 是该包物品数量，<code>%pack%</code> 是包 ID。</td></tr><tr><td><code>order</code></td><td><code>100</code></td><td>一级界面排序权重，升序。</td></tr></tbody></table><p>三点要注意：</p><ul><li><strong>包 ID 由目录相对路径决定</strong>，与 <code>pack.yml</code> 的内容无关。</li><li>不写 <code>pack.yml</code> 时整份走兜底：<code>minecraft:chest</code> 图标、目录名作显示名、lore 显示物品数量。</li><li><code>pack.yml</code> <strong>不会</strong>被物品加载器当作物品定义读取。</li></ul><p>可见的包目录深度由 <code>config.yml</code> 的 <code>data_directories.max_depth</code> 控制，超出深度的目录不会成为独立的包。</p><h2 id="一级界面槽位类型" tabindex="-1">一级界面槽位类型 <a class="header-anchor" href="#一级界面槽位类型" aria-label="Permalink to “一级界面槽位类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>pack_entry</code></td><td>包图标区域，按 <code>order</code> 升序填充（<code>order</code> 相同时按包 ID 字典序），超出则分页。点击进入该包的二级界面。</td></tr><tr><td><code>page_prev</code> / <code>page_next</code></td><td>翻页。</td></tr><tr><td><code>page_info</code></td><td>页码与统计信息。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr><tr><td><code>filler</code></td><td>装饰填充。</td></tr></tbody></table><p><code>pack_entry</code> 与 <code>page_info</code> 可用的占位符：</p><table tabindex="0"><thead><tr><th>占位符</th><th>可用位置</th><th>含义</th></tr></thead><tbody><tr><td><code>%pack%</code></td><td><code>pack_entry</code></td><td>包 ID。</td></tr><tr><td><code>%pack_name%</code></td><td><code>pack_entry</code></td><td>包显示名。</td></tr><tr><td><code>%pack_lore%</code></td><td><code>pack_entry</code></td><td>包 lore，取 <code>pack.yml</code> 的 <code>lore</code>，未定义时用兜底文本。</td></tr><tr><td><code>%count%</code></td><td><code>pack_entry</code></td><td>该包的物品数量，与 <code>%item_count%</code> 同值。</td></tr><tr><td><code>%item_count%</code></td><td><code>pack_entry</code></td><td>该包的物品数量。</td></tr><tr><td><code>%current_page%</code> / <code>%total_pages%</code></td><td><code>page_info</code></td><td>当前页码与总页数。</td></tr><tr><td><code>%pack_count%</code></td><td><code>page_info</code></td><td>物品包总数。</td></tr><tr><td><code>%item_count%</code></td><td><code>page_info</code></td><td>已加载物品定义总数。</td></tr></tbody></table><h2 id="二级界面槽位类型" tabindex="-1">二级界面槽位类型 <a class="header-anchor" href="#二级界面槽位类型" aria-label="Permalink to “二级界面槽位类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>item_entry</code></td><td>物品图标区域，按物品 ID 字典序填充，超出则分页。<strong>左键取一件</strong>，<strong>Shift + 左键取一整组</strong>；右键无效。</td></tr><tr><td><code>back</code></td><td>返回一级界面。</td></tr><tr><td><code>page_prev</code> / <code>page_next</code></td><td>翻页。</td></tr><tr><td><code>page_info</code></td><td>页码与统计信息。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr><tr><td><code>filler</code></td><td>装饰填充。</td></tr></tbody></table><p><code>item_entry</code> 的图标由<strong>物品定义本身渲染</strong>，槽位若写了 <code>lore</code> 会追加在物品原有 lore 之上。</p><p><code>page_info</code> 在二级界面可用 <code>%current_page%</code>、<code>%total_pages%</code>、<code>%pack%</code>（当前包 ID）、<code>%pack_name%</code>（当前包名），以及 <code>%item_count%</code> 与 <code>%count%</code>（都是当前包物品数）。</p><h2 id="每页容量由布局决定" tabindex="-1">每页容量由布局决定 <a class="header-anchor" href="#每页容量由布局决定" aria-label="Permalink to “每页容量由布局决定”">​</a></h2><p>每页放几个条目取决于布局里 <code>pack_entry</code> / <code>item_entry</code> 声明了多少格，不是固定值。默认布局两级都给了 21 格（第 2 至 4 行去掉两侧边框）。</p><p>改动这两个区域的格数会直接改变分页结果，翻页按钮无需同步调整。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to “相关页面”">​</a></h2><ul><li><a href="./commands.html">命令与权限</a></li><li><a href="./definitions.html">物品定义</a></li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};